mapper.select:
select
loseGoods.*,
students.header_img,
students.name,
students.tel,
loseType.type_name
from lose_goods loseGoods
left join students students on loseGoods.user_id = students.id
left join lose_type loseType on loseGoods.type_id = loseType.id

    and loseGoods.id = #{id}
    and loseGoods.goods_name like
        concat('%',#{goodsName},'%')

    and loseGoods.goods_img = #{goodsImg}
    and loseGoods.goods_info = #{goodsInfo}
    and loseGoods.type_id = #{typeId}
    and loseGoods.type = #{type}
    and loseGoods.user_id = #{userId}
    and loseGoods.create_time = #{createTime}
    and loseGoods.location = #{location}
    and loseGoods.has_money = #{hasMoney}
    and loseGoods.money = #{money}
    and loseGoods.img_list = #{imgList}
    and loseGoods.hidden = #{hidden}
    and students.header_img = #{headerImg}
    and students.name like concat('%',#{name},'%')
    and students.tel = #{tel}


    limit #{current},#{pageSize}

select count(*) from lose_goods loseGoods
left join students students on loseGoods.user_id = students.id
left join lose_type loseType on loseGoods.type_id = loseType.id

    and loseGoods.id = #{id}
    and loseGoods.goods_name like
        concat('%',#{goodsName},'%')

    and loseGoods.goods_img = #{goodsImg}
    and loseGoods.goods_info = #{goodsInfo}
    and loseGoods.type_id = #{typeId}
    and loseGoods.type = #{type}
    and loseGoods.user_id = #{userId}
    and loseGoods.create_time = #{createTime}
    and loseGoods.location = #{location}
    and loseGoods.has_money = #{hasMoney}
    and loseGoods.money = #{money}
    and loseGoods.img_list = #{imgList}
    and loseGoods.hidden = #{hidden}
    and students.header_img = #{headerImg}
    and students.name like concat('%',#{name},'%')
    and students.tel = #{tel}
